importQueue.process('import', 3, async (job) => {
  const { csvPath, adminEmail, dbConfig } = job.data;
  const client = await pool.connect();

  try {
    // 1. Split CSV into chunks and enqueue workers
    const fileStats = await fs.stat(csvPath);
    const fileSize = fileStats.size;
    const chunkSize = 5000000; // 5MB chunks
    const totalChunks = Math.ceil(fileSize / chunkSize);
    const { header, jobId } = await prepareImportMetadata(csvPath, client);

    // Create child jobs for parallel processing
    const chunkJobs = [];
    for (let i = 0; i < totalChunks; i++) {
      const start = i * chunkSize;
      const end = Math.min(start + chunkSize, fileSize);

      chunkJobs.push(importQueue.add('processChunk', {
        csvPath,
        adminEmail,
        header,
        dbConfig,
        start,
        end,
        jobId,
        chunkIndex: i
      }));
    }

    // Wait for all chunks to complete
    await Promise.all(chunkJobs);
    await finalizeImport(jobId, client);
    await sendCompletionEmail(adminEmail, true);

    return { success: true };
  } catch (error) {
    await sendCompletionEmail(adminEmail, false, error.message);
    throw error;
  } finally {
    client.release();
