});

// Chunk processing worker
importQueue.process('processChunk', 5, async (job) => {
  const { csvPath, header, dbConfig, start, end, jobId, chunkIndex } = job.data;
  const client = await pool.connect();

  try {
    // Read file chunk
    const buffer = Buffer.alloc(end - start);
    const handle = await fs.open(csvPath, 'r');
    await handle.read(buffer, 0, buffer.length, start);
    await handle.close();

    // Parse CSV chunk
    const csvContent = buffer.toString('utf-8');
    const results = parse(csvContent, {
      header: false,
      skipEmptyLines: true,
      preview: 0
    });

    // Process data
    const data = chunkIndex === 0 ? results.data.slice(1) : results.data;
    if (data.length === 0) return { chunkIndex, processed: 0 };

    // Batch insert
    const batchSize = 1000;
    for (let i = 0; i < data.length; i += batchSize) {
      const batch = data.slice(i, i + batchSize);
      await insertBatch(client, batch, header, dbConfig);
      job.progress((i / data.length) * 100);
    }

    return { chunkIndex, processed: data.length };
  } catch (error) {
    console.error(`Chunk ${chunkIndex} failed:`, error);
    throw error;
  } finally {
    client.release();
  }
});

