```html
<template>
  <v-container>
    <!-- Avatar Tabs -->
    <v-tabs v-model="currentTab" grow>
      <v-tab v-for="(options, category) in AVATAAARS_CATEGORIES" :key="category">
        {{ category }}
      </v-tab>
    </v-tabs>

    <!-- Tab Content -->
    <v-tabs-items v-model="currentTab">
      <v-tab-item v-for="(options, category) in AVATAAARS_CATEGORIES" :key="category">
        <v-container>
          <!-- Option Grid -->
          <v-layout row wrap>
            <v-flex xs4 v-for="option in options" :key="option">
              <v-item-group v-model="selectedOptions[category]" mandatory>
                <v-item>
                  <v-card 
                    @click="updateOption(category, option)"
                    class="option-card"
                    :class="{ 'selected': selectedOptions[category] === option }"
                  >
                    <v-img 
