                    ></v-img>
                  </v-card>
                </v-item>
              </v-item-group>
            </v-flex>
          </v-layout>
        </v-container>
      </v-tab-item>
    </v-tabs-items>

    <!-- Avatar Preview -->
    <v-container class="avatar-preview">
      <v-img 
        :src="avatarUrl"
        aspect-ratio="1"
        max-width="300"
        class="main-avatar"
      ></v-img>
    </v-container>
  </v-container>
</template>

<script>
export default {
  data() {
    return {
      // Avatar options
      selectedOptions: {},

      // Active tab index
      currentTab: 0,

      // Available categories and options
      AVATAAARS_CATEGORIES: {
        avatarStyle: ['Circle', 'Square'],
        topType: ['NoHair', 'Eyepatch', 'Hat', 'Hijab', 'Turban', 'WinterHat1', 'WinterHat2', 'WinterHat3', 'WinterHat4'],
        facialHairType: ['NoBeard', 'BeardMedium', 'BeardLight', 'BeardMagestic', 'MoustacheFancy', 'MoustacheMagnum'],
        hairColor: ['Black', 'Brown', 'BrownDark', 'Auburn', 'Blonde', 'BlondeGolden', 'SilverGray'],
        hatColor: ['Black', 'Brown', 'BrownDark', 'Pink', 'Blue', 'Blue01', 'Green'],
        facialHairColor: ['Black', 'Brown', 'BrownDark', 'Blonde', 'BlondeGolden'],
        accessoriesType: ['NoAccessory', 'Kurt', 'Glasses', 'Sunglasses', 'EyePatch'],
        clotheType: ['BlazerShirt', 'BlazerSweater', 'ShirtCrewNeck', 'ShirtScoopNeck', 'ShirtVNeck', 'Sweater'],
        clotheColor: ['White', 'Blue', 'Black', 'Red', 'Green', 'Yellow'],
        graphicType: ['NoGraphic', 'Bat', 'Cumbia', 'Deer', 'Diamond', 'Hola', 'Pizza'],
        eyeType: ['Happy', 'Sad', 'Angry', 'Naughty', 'Surprised'],
        eyebrowType: ['Default', 'DefaultNatural', 'Up', 'UpDown'],
        mouthType: ['Happy', 'Sad', 'Smile', 'Frown', 'Serious', 'Vomit'],
        skinColor: ['Light', 'Medium', 'Dark', 'Black', 'Yellow']
      }
    };
  },
  computed: {
    /**
     * Generates the main avatar URL based on selected options
     */
    avatarUrl() {
      return this.generateAvataaarUrl(this.selectedOptions);
    }
  },
  methods: {
    /**
     * Generates an avataaars.io URL from current options
     */
    generateAvataaarUrl(options) {
      const base = "https://avataaars.io/";
      const validOptions = Object.entries(options)
        .filter(([key, value]) => 
          this.AVATAAARS_CATEGORIES[key]?.includes(value)
        );

      if (validOptions.length === 0) return base;

      const params = validOptions.map(([key, value]) => 
        `${encodeURIComponent(key)}=${encodeURIComponent(value)}`
      ).join('&');

      return `${base}?${params}`;
    },

    /**
     * Generates a preview URL for a specific option
     */
    getPreviewUrl(category, option) {
      return this.generateAvataaarUrl({
        ...this.selectedOptions,
        [category]: option
      });
    },

    /**
     * Updates an option and persists to local storage
     */
    updateOption(category, value) {
      this.selectedOptions = {
        ...this.selectedOptions,
        [category]: value
      };
      this.saveOptions();
    },

    /**
     * Saves current options to local storage
     */
    saveOptions() {
      localStorage.setItem('avatar_options', JSON.stringify(this.selectedOptions));
    },

    /**
     * Loads saved options from local storage
     */
    loadOptions() {
      const stored = localStorage.getItem('avatar_options');
      if (stored) {
        this.selectedOptions = JSON.parse(stored);
      } else {
        // Set default options
        this.selectedOptions = {
          avatarStyle: 'Circle',
          topType: 'Hijab',
          hairColor: 'BlondeGolden',
          facialHairType: 'NoBeard',
          accessoriesType: 'NoAccessory',
          clotheType: 'ShirtVNeck',
          clotheColor: 'Blue',
          eyeType: 'Happy',
          eyebrowType: 'Default',
          mouthType: 'Smile',
          skinColor: 'Medium'
        };
      }
    }
  },
  mounted() {
    this.loadOptions();
  }
};
</script>

