```c
// System call implementations
uint64 sys_directory_walker(void) {
  int start_inode;
  argint(0, &start_inode);
  struct inode *ip = iget(ROOTDEV, start_inode);
  ilock(ip);

  // Directory traversal logic using xv6's dirread/dirslookup
  struct dirent de;
  struct inode *entry_ip;
  int off;

  for(off = 0; off < ip->size; off += sizeof(de)) {
    readi(ip, (char*)&de, off, sizeof(de));
    if(de.inum == 0)
      continue;

    entry_ip = iget(ROOTDEV, de.inum);
    ilock(entry_ip);

    // Print entry information
    printf("%s (inode %d)\n", de.name, de.inum);

    if(entry_ip->type == T_DIR) {
      // Recursive directory traversal
      sys_directory_walker(entry_ip->inum);
    }

    iunlock(entry_ip);
    iput(entry_ip);
  }

  iunlock(ip);
  iput(ip);
  return 0;
}

uint64 sys_directory_eraser(void) {
  int inum;
  argint(0, &inum);
  struct inode *ip = iget(ROOTDEV, inum);
  ilock(ip);

  // Zero out inode data blocks
  for(int i = 0; i < NDIRECT; i++) {
    if(ip->addrs[i]) {
      bzero(ROOTDEV, ip->addrs[i]);
      bfree(ROOTDEV, ip->addrs[i]);
    }
  }

  // Clear inode
  ip->type = 0;
  iupdate(ip);
  iunlock(ip);
  iput(ip);

  // Update bitmap
  char *buf = kalloc();
  readi(get_inode(ROOTDEV, ROOTINO), buf, IBLOCK(inum, sb)*BSIZE, BSIZE);
  char *cp = buf + (inum % IPB)*sizeof(struct inode);
  struct inode *dip = (struct inode*)cp;
  dip->type = 0;
  writei(get_inode(ROOTDEV, ROOTINO), buf, IBLOCK(inum, sb)*BSIZE, BSIZE);
  kfree(buf);

  return 0;
}
