## Complete Python Tools Implementation

### directoryWalker.py (Complete)
```python
import struct
import os

BSIZE = 4096
INODE_SIZE = 64
DIRENT_SIZE = 16
NDIRECT = 12

def read_superblock(f):
    f.seek(BSIZE)
    raw = f.read(BSIZE)
    return {
        'size': struct.unpack('<I', raw[0:4])[0],
        'nblocks': struct.unpack('<I', raw[4:8])[0],
        'ninodes': struct.unpack('<I', raw[8:12])[0],
        'nlog': struct.unpack('<I', raw[12:16])[0],
        'logstart': struct.unpack('<I', raw[16:20])[0],
        'inodestart': struct.unpack('<I', raw[20:24])[0],
        'bmapblock': struct.unpack('<I', raw[24:28])[0],
    }

def read_inode(f, inodestart, inum):
    block_num = inodestart + ((inum - 1) // (BSIZE // INODE_SIZE))
    offset_in_block = (inum - 1) % (BSIZE // INODE_SIZE) * INODE_SIZE
    f.seek(block_num * BSIZE + offset_in_block)
    raw = f.read(INODE_SIZE)
    type_map = {0: 'unused', 1: 'directory', 2: 'file', 3: 'device'}
    return {
        'type': struct.unpack('<H', raw[0:2])[0],
        'type_str': type_map.get(struct.unpack('<H', raw[0:2])[0], 'unknown'),
        'major': struct.unpack('<H', raw[2:4])[0],
        'minor': struct.unpack('<H', raw[4:6])[0],
        'nlink': struct.unpack('<H', raw[6:8])[0],
        'size': struct.unpack('<I', raw[8:12])[0],
        'addrs': list(struct.unpack('<13I', raw[12:64]))
    }

def get_directory_entries(f, inode):
    entries = []
    for addr in inode['addrs'][:12]:
        if addr == 0:
            continue
        f.seek(addr * BSIZE)
        block = f.read(BSIZE)
        for i in range(0, len(block), DIRENT_SIZE):
            if i + DIRENT_SIZE > len(block):
                break
            dirent = block[i:i+DIRENT_SIZE]
            inum = struct.unpack('<H', dirent[0:2])[0]
            name = dirent[2:16].split(b'\x00', 1)[0].decode('ascii', errors='ignore')
            if inum != 0:
                entries.append({'inum': inum, 'name': name})
    return entries

def walk_directory(f, inodestart, inum, path, visited, max_depth=10, current_depth=0):
    if current_depth > max_depth:
        return []

    if inum in visited:
        return []
    visited.add(inum)

    inode = read_inode(f, inodestart, inum)
    if inode['type'] != 1:
        return []

    results = []
    entries = get_directory_entries(f, inode)

    for entry in entries:
        if entry['inum'] == 0:
            continue

        full_path = f"{path}/{entry['name']}"
        results.append(full_path)

        child_inode = read_inode(f, inodestart, entry['inum'])
        if child_inode['type'] == 1:
            child_results = walk_directory(f, inodestart, entry['inum'], full_path, visited, max_depth, current_depth + 1)
            results.extend(child_results)

    return results

def main():
    import sys
    if len(sys.argv) < 2:
        print("Usage: directoryWalker.py <disk_image> [start_inode]")
        return

    disk_image = sys.argv[1]
    start_inode = int(sys.argv[2]) if len(sys.argv) > 2 else 1

    with open(disk_image, 'rb') as f:
        superblock = read_superblock(f)
        print(f"Starting directory walk from inode {start_inode}")
        visited = set()
        results = walk_directory(f, superblock['inodestart'], start_inode, '.', visited)

        for path in sorted(results):
            print(path)

if __name__ == '__main__':
    main()
```

