using System;
using Teigha.Runtime;
using Teigha.DatabaseServices;
using Multicad.ApplicationServices;
using Multicad.DatabaseServices;
using Multicad.Runtime;

public class TablePrimitiveEmbedder
{
    /// <summary>
    /// Embeds geometric primitives into a specified McTable cell in nanoCAD.
    /// </summary>
    /// <param name="table">Target McTable object</param>
    /// <param name="rowIndex">Zero-based row index</param>
    /// <param name="columnIndex">Zero-based column index</param>
    /// <param name="geometryList">List of EntityGeometry objects to embed</param>
    public void EmbedPrimitivesToTableCell(
        McTable table, 
        int rowIndex, 
        int columnIndex, 
        List<EntityGeometry> geometryList)
    {
        if (table == null)
            throw new ArgumentNullException(nameof(table));

        using (Transaction transaction = new Transaction(table.Database, "Embed Primitives"))
        {
            try
            {
                transaction.Start();

                // Validate indices
                if (rowIndex < 0 || rowIndex >= table.Rows.Count)
                    throw new ArgumentOutOfRangeException(nameof(rowIndex), "Row index out of range");

                if (columnIndex < 0 || columnIndex >= table.Columns.Count)
                    throw new ArgumentOutOfRangeException(nameof(columnIndex), "Column index out of range");

                // Access target cell
                McRow row = table.Rows[rowIndex];
                McCell cell = row.Cells[columnIndex];

                // Append each geometry to the cell
                foreach (EntityGeometry entity in geometryList)
                {
                    cell.Geometry.Append(entity); // Actual Multicad API method
                }

                transaction.Commit();
            }
            catch (Exception ex)
            {
                transaction.Abort();
                throw new Exception("Failed to embed primitives into table cell", ex);
            }
        }
    }
}

