class ChessController {
public:
    ChessController() : window(sf::VideoMode(1000, 640), "Chess Game") {
        game.players[0].name = "Player 1";
        game.players[1].name = "Player 2";
        game.loadRatings();
    }

    void run() {
        while(window.isOpen()) {
            processEvents();
            window.clear();
            renderer.drawBoard();
            renderer.drawPieces(game);
            renderer.drawUI(game, showSettings, mousePosition);

            if(showRatingWindow) {
                renderer.drawRatingWindow(game, mousePosition);
            }

            window.display();
        }
    }

private:
    void processEvents() {
        sf::Event event;
        while(window.pollEvent(event)) {
            if(event.type == sf::Event::Closed) {
                window.close();
            }

            if(event.type == sf::Event::MouseButtonPressed) {
                mousePosition = sf::Mouse::getPosition(window);
                handleMouseClick(event.mouseButton.x, event.mouseButton.y);
            }

            if(event.type == sf::Event::KeyPressed) {
                handleKeyPress(event.key.code);
            }
        }
    }

    void handleKeyPress(int keyCode) {
        // Handle input for settings panel
        if(showSettings && activeInput) {
            int playerIndex = *activeInput;
            std::string& name = game.players[playerIndex].name;

            if(keyCode >= sf::Keyboard::A && keyCode <= sf::Keyboard::Z) {
                char letter = 'A' + (keyCode - sf::Keyboard::A);
                name += letter;
            }
            else if(keyCode == sf::Keyboard::BackSpace && !name.empty()) {
                name.pop_back();
            }
        }
    }

    void handleMouseClick(int x, int y) {
        // Handle board clicks
        if(x < 640 && y < 640 && !showRatingWindow) {
            int squareX = x / 80;
            int squareY = y / 80;

            if(selectedSquare.has_value()) {
                auto [fromX, fromY] = selectedSquare.value();
                game.movePiece(fromX, fromY, squareX, squareY);
                selectedSquare.reset();
            } else if(game.board[squareY][squareX]) {
                selectedSquare = std::make_pair(squareX, squareY);
            }
        }

        // Handle UI clicks
        else if(!showSettings && !showRatingWindow) {
            // Check main buttons
            if(isInBounds(x, y, 660, 120, 240, 30)) { // Start Game
                game.setupBoard();
                selectedSquare.reset();
                game.currentTurn = PlayerColor::WHITE;
            }
            else if(isInBounds(x, y, 660, 160, 240, 30)) { // Player Rating
                showRatingWindow = true;
            }
            else if(isInBounds(x, y, 660, 200, 240, 30)) { // Settings
                showSettings = true;
                activeInput.reset();
            }
        }

        // Handle settings panel
        if(showSettings) {
            // Check close button
            if(isInBounds(x, y, 350, 250, 100, 30)) { // Save
                showSettings = false;
                activeInput.reset();
                game.saveRatings();
            }

            // Check input fields
            if(isInBounds(x, y, 110, 150, 200, 30)) { // Player 1
                activeInput = 0;
            }
            else if(isInBounds(x, y, 110, 200, 200, 30)) { // Player 2
                activeInput = 1;
            }
        }

        // Handle rating window
        if(showRatingWindow) {
            if(isInBounds(x, y, 600, 350, 80, 30)) { // Close
                showRatingWindow = false;
            }
        }
    }

    bool isInBounds(int x, int y, int bx, int by, int bw, int bh) {
        return x > bx && x < bx + bw && y > by && y < by + bh;
    }

    sf::RenderWindow window;
    ChessGame game;
    ChessRenderer renderer{window};
    sf::Vector2i mousePosition;
    std::optional<std::pair<int, int>> selectedSquare;
    bool showSettings = false;
    bool showRatingWindow = false;
    std::optional<int> activeInput; // 0 for player1, 1 for player2
};

int main() {
    ChessController controller;
    controller.run();
    return 0;
}
```

