```kotlin
class PhotoListFragment : Fragment() {

    private lateinit var photoViewModel: PhotoViewModel
    private lateinit var binding: FragmentPhotoListBinding
    private lateinit var photoAdapter: PhotoAdapter

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        binding = FragmentPhotoListBinding.inflate(inflater, container, false)

        photoAdapter = PhotoAdapter()
        binding.recyclerView.adapter = photoAdapter

        photoViewModel = ViewModelProvider(this)[PhotoViewModel::class.java]

        setupSearchView()
        setupSortSpinner()
        observeViewModel()

        return binding.root
    }

    private fun setupSearchView() {
        binding.searchView.setOnQueryTextListener(object : SearchView.OnQueryTextListener {
            override fun onQueryTextSubmit(query: String?): Boolean {
                query?.let { photoViewModel.updateSearchQuery(it) }
                return true
            }

            override fun onQueryTextChange(newText: String?): Boolean {
                newText?.let { photoViewModel.updateSearchQuery(it) }
                return true
            }
        })
    }

    private fun setupSortSpinner() {
        val sortOptions = arrayOf("Name", "Price", "Description")
        val adapter = ArrayAdapter(requireContext(), android.R.layout.simple_spinner_item, sortOptions)
        binding.spinnerSort.adapter = adapter

        binding.spinnerSort.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(
                parent: AdapterView<*>, view: View?, position: Int, id: Long
            ) {
                val field = when (position) {
                    0 -> "name"
                    1 -> "price"
                    2 -> "description"
                    else -> "name"
                }
                photoViewModel.updateOrderingField(field)
            }

            override fun onNothingSelected(parent: AdapterView<*>) {}
        }
    }

    private fun observeViewModel() {
        photoViewModel.photos.observe(viewLifecycleOwner) {
            photoAdapter.submitList(it)
        }
    }
}
```

