import { Injectable, OnModuleInit } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { CreateItemDto } from './item.dto';
import { ItemDocument } from './item.model';
import * as xmlparser from 'fast-xml-parser';

@Injectable()
export class ItemsService implements OnModuleInit {
  private xmlData: any;

  constructor(
    @InjectModel('Item') private readonly itemModel: Model<ItemDocument>
  ) {}

  async onModuleInit() {
    await this.loadXMLData();
    await this.migrateData();
  }

  private async loadXMLData() {
    // Simulated XML loading and validation
    try {
      const xmlContent = await fs.promises.readFile('items.xml', 'utf-8');
      const parsed = xmlparser.parse(xmlContent);
      this.xmlData = parsed.Items.Item;
    } catch (error) {
      console.error(`XML Load Error: ${error.message}`);
      throw error;
    }
  }

  private async migrateData() {
    // Data migration with validation
    try {
      const existing = await this.itemModel.countDocuments();
      if (existing > 0) return;

      const mappedData = this.xmlData.map(item => ({
        externalId: item.Id,
        name: item.Name,
        category: item.Category || 'Uncategorized',
        price: parseFloat(item.Price)
      }));

      await this.itemModel.insertMany(mappedData);
    } catch (error) {
      console.error(`Migration Error: ${error.message}`);
      throw error;
    }
  }

  // SQL-to-MongoDB query transformations
  async sqlQueryTransformer(queryType: string) {
    switch (queryType) {
      case 'price-filter':
        // SQL: SELECT * FROM items WHERE price > 10
        return this.itemModel.find({ price: { $gt: 10 } });

      case 'text-search':
        // SQL: SELECT * FROM items WHERE name LIKE '%apple%'
        return this.itemModel.find({ 
          name: { $regex: 'apple', $options: 'i' }
        });

      case 'group-aggregation':
        // SQL: SELECT category, COUNT(*) FROM items GROUP BY category
        return this.itemModel.aggregate([
          {
            $group: {
              _id: '$category',
              count: { $sum: 1 }
            }
          }
        ]);

      case 'join-equivalent':
        // SQL: SELECT * FROM items i JOIN categories c ON i.category_id = c.id
        return this.itemModel.aggregate([
          {
            $lookup: {
              from: 'categories',
              localField: 'category',
              foreignField: 'name',
              as: 'categoryDetails'
            }
          }
        ]);
    }
  }
}

