import { Controller, Get, Post, Body, Query } from '@nestjs/common';
import { ItemsService } from './items.service';
import { CreateItemDto } from './item.dto';

@Controller('items')
export class ItemsController {
  constructor(private readonly itemsService: ItemsService) {}

  @Get()
  async searchItems(@Query('name') name?: string) {
    return name 
      ? this.itemsService.sqlQueryTransformer('text-search')
      : this.itemsService.findAll();
  }

  @Post()
  async createItems(@Body() createItemDto: CreateItemDto[]) {
    return this.itemsService.bulkCreate(createItemDto);
  }
}

